#!/usr/bin/env bash
# Reproducible schema statistics for the installed Shopware MariaDB. READ-ONLY (SELECT only).
# Usage: ./schema-stats.sh > stats-output.txt
M() { podman exec instance-database-1 mariadb -uroot -proot shopware -t -e "$1" 2>/dev/null; }
S="table_schema='shopware'"
echo "## version"; M "select version()"
echo "## tables (BASE TABLE) / views"; M "select table_type,count(*) from information_schema.tables where $S group by 1"
echo "## columns"; M "select count(*) from information_schema.columns where $S"
echo "## indexes (distinct table,index) / index columns by type"; M "select count(*) idx from (select distinct table_name,index_name from information_schema.statistics where $S) x"
M "select index_type,count(distinct table_name,index_name) idx from information_schema.statistics where $S group by 1"
echo "## primary keys / unique / non-unique"; M "select if(index_name='PRIMARY','PRIMARY',if(non_unique=0,'UNIQUE','NONUNIQUE')) k,count(distinct table_name,index_name) from information_schema.statistics where $S group by 1"
echo "## foreign keys"; M "select count(*) from information_schema.referential_constraints where constraint_schema='shopware'"
echo "## FK rules"; M "select delete_rule,update_rule,count(*) from information_schema.referential_constraints where constraint_schema='shopware' group by 1,2 order by 3 desc"
echo "## triggers"; M "select count(*) from information_schema.triggers where trigger_schema='shopware'"
echo "## generated/virtual columns"; M "select generation_expression is not null and generation_expression<>'' g, extra, count(*) from information_schema.columns where $S and (extra like '%GENERATED%' or extra like '%VIRTUAL%' or extra like '%PERSISTENT%' or extra like '%STORED%') group by 1,2"
echo "## check constraints (total / JSON_VALID)"; M "select count(*), sum(check_clause like '%json_valid%') from information_schema.check_constraints where constraint_schema='shopware'"
echo "## fulltext indexes"; M "select count(distinct table_name,index_name) from information_schema.statistics where $S and index_type='FULLTEXT'"
echo "## ON UPDATE CURRENT_TIMESTAMP"; M "select count(*) from information_schema.columns where $S and extra like '%on update%'"
echo "## auto_increment columns"; M "select table_name,column_name,column_type from information_schema.columns where $S and extra like '%auto_increment%'"
echo "## enum/set columns"; M "select count(*) from information_schema.columns where $S and data_type in ('enum','set')"
echo "## distinct column types"; M "select column_type, count(*) n from information_schema.columns where $S group by 1 order by 2 desc"
echo "## BINARY(16) classification: id col (id/*_id), other"; M "select if(column_name='id' or column_name like '%\\_id','id/fk-like','other') k,count(*) from information_schema.columns where $S and column_type='binary(16)' group by 1"
echo "## BINARY(16) non-id-named columns"; M "select table_name,column_name from information_schema.columns where $S and column_type='binary(16)' and not (column_name='id' or column_name like '%\\_id') order by 1,2"
echo "## other binary/varbinary/blob"; M "select table_name,column_name,column_type from information_schema.columns where $S and (data_type in ('varbinary','blob','tinyblob','mediumblob','longblob') or (data_type='binary' and column_type<>'binary(16)')) order by 3,1,2"
echo "## json columns (data_type json) and longtext w/ json_valid check"; M "select data_type,count(*) from information_schema.columns where $S and data_type in ('json') group by 1"
M "select count(*) from information_schema.check_constraints where constraint_schema='shopware' and check_clause like '%json_valid%'"
echo "## charset/collation by column"; M "select character_set_name,collation_name,count(*) from information_schema.columns where $S and character_set_name is not null group by 1,2"
echo "## table collations"; M "select table_collation,count(*) from information_schema.tables where $S group by 1"
echo "## unique indexes on string columns (not PK)"; M "select s.table_name,s.index_name,group_concat(s.column_name order by seq_in_index) cols, group_concat(c.collation_name order by seq_in_index) colls from information_schema.statistics s join information_schema.columns c on c.table_schema=s.table_schema and c.table_name=s.table_name and c.column_name=s.column_name where s.$S and s.non_unique=0 and s.index_name<>'PRIMARY' group by s.table_name,s.index_name having sum(c.character_set_name is not null)>0 order by 1,2"
echo "## triggers"; M "select trigger_name,event_manipulation,event_object_table,action_timing,action_statement from information_schema.triggers where trigger_schema='shopware'\\G"
echo "## generated columns"; M "select table_name,column_name,column_type,extra,generation_expression from information_schema.columns where $S and (extra like '%GENERATED%' or extra like '%VIRTUAL%' or extra like '%PERSISTENT%')"
echo "## composite FKs"; M "select constraint_name,table_name,group_concat(column_name order by ordinal_position) cols,referenced_table_name from information_schema.key_column_usage where $S and referenced_table_name is not null group by table_name,constraint_name,referenced_table_name having count(*)>1 order by 2"
echo "## unsigned / int types"; M "select column_type,count(*) from information_schema.columns where $S and data_type like '%int%' group by 1 order by 2 desc"
echo "## DATETIME/TIMESTAMP"; M "select column_type,count(*) from information_schema.columns where $S and data_type in ('datetime','timestamp','date','time') group by 1"
echo "## DOUBLE/DECIMAL/FLOAT"; M "select column_type,count(*) from information_schema.columns where $S and data_type in ('double','decimal','float') group by 1"
echo "## JSON-checked columns, distinct (column-level and table-level checks both appear in check_constraints, so count distinct columns)"
M "select c.column_type,c.collation_name,count(distinct c.table_name,c.column_name) cols from information_schema.columns c join information_schema.check_constraints k on k.constraint_schema=c.table_schema and k.table_name=c.table_name and k.check_clause like concat('%json_valid(\`',c.column_name,'\`)%') where c.table_schema='shopware' group by 1,2"
echo "## JSON-checked columns not utf8mb4_bin"; M "select distinct c.table_name,c.column_name from information_schema.columns c join information_schema.check_constraints k on k.constraint_schema=c.table_schema and k.table_name=c.table_name and k.check_clause like concat('%json_valid(\`',c.column_name,'\`)%') where c.table_schema='shopware' and c.collation_name<>'utf8mb4_bin'"
echo "## named json.* check constraints"; M "select count(*) from information_schema.check_constraints where constraint_schema='shopware' and constraint_name like 'json.%'"
echo "## non-JSON checks"; M "select table_name,constraint_name,check_clause from information_schema.check_constraints where constraint_schema='shopware' and check_clause not like '%json_valid%'"
echo "## product camelCase binary(16) columns"; M "select count(*) from information_schema.columns where table_schema='shopware' and table_name='product' and column_type='binary(16)' and column_name not like '%id'"
echo "## composite FKs involving version_id / all FKs"; M "select count(*) from (select 1 from information_schema.key_column_usage where $S and referenced_table_name is not null group by table_name,constraint_name having count(*)>1 and sum(column_name like '%version_id')>0) x"
M "select count(*) from (select 1 from information_schema.key_column_usage where $S and referenced_table_name is not null group by table_name,constraint_name having count(*)=1) x"
echo "## FKs referencing a column other than id/version_id"; M "select count(*) from information_schema.key_column_usage where $S and referenced_table_name is not null and referenced_column_name not in ('id','version_id')"
echo "## composite FKs by delete rule"; M "select r.delete_rule,count(*) from information_schema.referential_constraints r where r.constraint_schema='shopware' and (select count(*) from information_schema.key_column_usage k where k.constraint_schema=r.constraint_schema and k.table_name=r.table_name and k.constraint_name=r.constraint_name)>1 group by 1"
echo "## SET NULL FKs that include a NOT NULL *version_id column"; M "select count(*) from information_schema.referential_constraints r where r.constraint_schema='shopware' and r.delete_rule='SET NULL' and exists (select 1 from information_schema.key_column_usage k join information_schema.columns c on c.table_schema=k.table_schema and c.table_name=k.table_name and c.column_name=k.column_name where k.constraint_schema=r.constraint_schema and k.table_name=r.table_name and k.constraint_name=r.constraint_name and k.column_name like '%version_id' and c.is_nullable='NO')"
echo "## binary(16) columns with a default (all are *version_id)"; M "select column_name,count(*) from information_schema.columns where $S and column_type='binary(16)' and column_default<>'NULL' group by 1"
